InSessionAuthAsyncWaiter::InSessionAuthAsyncWaiter(
    InSessionAuth* proxy) : proxy_(proxy) {}

InSessionAuthAsyncWaiter::~InSessionAuthAsyncWaiter() = default;

void InSessionAuthAsyncWaiter::RequestToken(
    Reason reason, const absl::optional<std::string>& prompt, RequestTokenReplyPtr* out_reply) {
  base::RunLoop loop;
  proxy_->RequestToken(std::move(reason),std::move(prompt),
      base::BindOnce(
          [](base::RunLoop* loop,
             RequestTokenReplyPtr* out_reply
,
             RequestTokenReplyPtr reply) {*out_reply = std::move(reply);
            loop->Quit();
          },
          &loop,
          out_reply));
  loop.Run();
}

RequestTokenReplyPtr InSessionAuthAsyncWaiter::RequestToken(
    Reason reason, const absl::optional<std::string>& prompt) {
  RequestTokenReplyPtr async_wait_result;
  RequestToken(std::move(reason),std::move(prompt),&async_wait_result);
  return async_wait_result;
}

void InSessionAuthAsyncWaiter::CheckToken(
    Reason reason, const std::string& token, bool* out_valid) {
  base::RunLoop loop;
  proxy_->CheckToken(std::move(reason),std::move(token),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_valid
,
             bool valid) {*out_valid = std::move(valid);
            loop->Quit();
          },
          &loop,
          out_valid));
  loop.Run();
}

bool InSessionAuthAsyncWaiter::CheckToken(
    Reason reason, const std::string& token) {
  bool async_wait_result;
  CheckToken(std::move(reason),std::move(token),&async_wait_result);
  return async_wait_result;
}






